-- Recontar propiedades por ubicación
update locations l set property_count = coalesce(sub.c, 0) from (
  select loc_id, count(*) c from (
    select unnest(array[sector_id, city_id, province_id]) loc_id
    from properties where status = 'PUBLISHED'
  ) x where loc_id is not null group by loc_id
) sub where l.id = sub.loc_id;

-- Sincronizar secuencias de códigos
select setval('property_code_seq', greatest(1, coalesce((select max(nullif(regexp_replace(code, '\D', '', 'g'), '')::int) from properties), 0)), true);
select setval('project_code_seq',  greatest(1, coalesce((select max(nullif(regexp_replace(code, '\D', '', 'g'), '')::int) from projects), 0)), true);

commit;

